import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 32 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(32)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import math
import time
from scipy.optimize import minimize, linprog, NonlinearConstraint


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.72
    N = 32
    rng = np.random.default_rng(20240607)

    def lp_radii(centers):
        x = centers[:, 0]; y = centers[:, 1]
        A = []; b = []
        iu = np.triu_indices(N, 1)
        for i, j in zip(*iu):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            row = np.zeros(N); row[i] = 1.0; row[j] = 1.0
            A.append(row); b.append(d)
        for i in range(N):
            w = min(x[i], 1.0 - x[i], y[i], 1.0 - y[i])
            row = np.zeros(N); row[i] = 1.0
            A.append(row); b.append(max(w, 0.0))
        res = linprog(-np.ones(N), A_ub=np.array(A), b_ub=np.array(b),
                      bounds=[(0.0, None)] * N, method='highs')
        if not res.success:
            return None
        return res.x

    def shrink(centers, radii):
        r = radii.copy()
        r = np.minimum(r, np.minimum(centers[:, 0], 1.0 - centers[:, 0]))
        r = np.minimum(r, np.minimum(centers[:, 1], 1.0 - centers[:, 1]))
        for _ in range(200):
            d = centers[:, None, :] - centers[None, :, :]
            dist = np.sqrt((d ** 2).sum(-1))
            s = r[:, None] + r[None, :]
            iu = np.triu_indices(N, 1)
            viol = s[iu] - dist[iu]
            if viol.max() <= 0:
                break
            for k in np.where(viol > 0)[0]:
                i, j = iu[0][k], iu[1][k]
                ex = s[i, j] - dist[i, j]
                tot = r[i] + r[j]
                if tot > 0:
                    r[i] = max(1e-9, r[i] - 0.5 * ex * r[i] / tot - 1e-15)
                    r[j] = max(1e-9, r[j] - 0.5 * ex * r[j] / tot - 1e-15)
        return np.maximum(r, 1e-9)

    iu = np.triu_indices(N, 1)

    def unpack(z):
        return z[:2 * N].reshape(N, 2), z[2 * N:]

    def obj(z):
        return -z[2 * N:].sum()

    def obj_g(z):
        g = np.zeros_like(z); g[2 * N:] = -1.0
        return g

    def cons_f(z):
        c, r = unpack(z)
        d = c[:, None, :] - c[None, :, :]
        dist = np.sqrt((d ** 2).sum(-1) + 1e-30)
        s = r[:, None] + r[None, :]
        out = [c[:, 0] - r, 1.0 - c[:, 0] - r, c[:, 1] - r, 1.0 - c[:, 1] - r]
        out.append(dist[iu] - s[iu])
        return np.concatenate(out)

    def cons_j(z):
        c, r = unpack(z)
        d = c[:, None, :] - c[None, :, :]
        dist = np.sqrt((d ** 2).sum(-1) + 1e-30)
        np.fill_diagonal(dist, 1.0)
        m = len(iu[0])
        J = np.zeros((4 * N + m, 3 * N))
        for i in range(N):
            J[i, 2 * i] = 1.0; J[i, 2 * N + i] = -1.0
            J[N + i, 2 * i] = -1.0; J[N + i, 2 * N + i] = -1.0
            J[2 * N + i, 2 * i + 1] = 1.0; J[2 * N + i, 2 * N + i] = -1.0
            J[3 * N + i, 2 * i + 1] = -1.0; J[3 * N + i, 2 * N + i] = -1.0
        for k in range(m):
            i, j = iu[0][k], iu[1][k]
            row = 4 * N + k
            dx = c[i, 0] - c[j, 0]; dy = c[i, 1] - c[j, 1]
            dd = dist[i, j]
            J[row, 2 * i] = dx / dd; J[row, 2 * i + 1] = dy / dd
            J[row, 2 * j] = -dx / dd; J[row, 2 * j + 1] = -dy / dd
            J[row, 2 * N + i] = -1.0; J[row, 2 * N + j] = -1.0
        return J

    bounds = [(0.0, 1.0), (0.0, 1.0)] * N + [(1e-9, 0.5)] * N
    nlc = NonlinearConstraint(cons_f, 0.0, np.inf, jac=cons_j)

    def to_z(c, r):
        z = np.empty(3 * N); z[:2 * N] = c.ravel(); z[2 * N:] = r
        return z

    def hex_seed():
        rows = [6, 5, 6, 5, 6, 4]
        r0 = 1.0 / 12.0
        dy = math.sqrt(3.0) * r0
        pts = []
        for i, cnt in enumerate(rows):
            y = r0 + i * dy
            x0 = r0 if i % 2 == 0 else 2.0 * r0
            for k in range(cnt):
                pts.append((x0 + k * 2.0 * r0, y, r0))
        return np.array(pts)

    def random_seed():
        c = rng.uniform(0.05, 0.95, size=(N, 2))
        r = lp_radii(c)
        if r is None:
            r = np.full(N, 0.05)
        return np.column_stack([c, r])

    def row_seed(k, rows):
        r0 = 1.0 / (2.0 + (k - 1) * math.sqrt(3.0))
        dy = math.sqrt(3.0) * r0
        pts = []
        for i, cnt in enumerate(rows):
            y = r0 + i * dy
            x0 = r0 if i % 2 == 0 else 2.0 * r0
            for kk in range(cnt):
                pts.append((x0 + kk * 2.0 * r0, y, r0))
        return np.array(pts)

    def compositions(n, k):
        if k == 1:
            yield (n,)
            return
        for first in range(1, n - k + 2):
            for rest in compositions(n - first, k - 1):
                yield (first,) + rest

    row_seed_list = []
    seen = set()
    for k in (5, 6, 7):
        comps = [c for c in compositions(N, k) if max(c) - min(c) <= 2]
        step = max(1, len(comps) // 4)
        for c in comps[::step][:4]:
            if c not in seen:
                seen.add(c)
                pts = row_seed(k, c)
                row_seed_list.append(pts[:, :2])
    for c in [(4, 4, 4, 4, 4, 4, 4, 4), (3, 5, 3, 5, 3, 5, 3, 5)]:
        if c not in seen:
            seen.add(c)
            pts = row_seed(len(c), c)
            row_seed_list.append(pts[:, :2])
    row_idx = [0]

    def next_row_seed():
        if not row_seed_list:
            return random_seed()
        c = row_seed_list[row_idx[0] % len(row_seed_list)].copy()
        row_idx[0] += 1
        c = np.clip(c, 0.0, 1.0)
        r = lp_radii(c)
        if r is None:
            r = np.full(N, 0.05)
        return np.column_stack([c, shrink(c, r)])

    best = None; best_score = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.shape == (N, 3):
            c = s[:, :2].copy()
            r = shrink(c, s[:, 2].copy())
            rlp = lp_radii(c)
            if rlp is not None and rlp.sum() > r.sum():
                r = shrink(c, rlp)
            best = np.column_stack([c, r])
            best_score = r.sum()

    if best is None:
        h = hex_seed()
        c = h[:, :2]; r = shrink(c, h[:, 2])
        rlp = lp_radii(c)
        if rlp is not None and rlp.sum() > r.sum():
            r = shrink(c, rlp)
        best = np.column_stack([c, r]); best_score = r.sum()

    def run_opt(seed, maxiter=400):
        z0 = to_z(seed[:, :2], seed[:, 2])
        try:
            res = minimize(obj, z0, jac=obj_g, method='SLSQP',
                           constraints=[{'type': 'ineq', 'fun': cons_f, 'jac': cons_j}],
                           bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': 1e-14})
        except Exception:
            return None
        if res.x is None:
            return None
        c, r = unpack(res.x)
        c = np.clip(c, 0.0, 1.0)
        r = shrink(c, r)
        rlp = lp_radii(c)
        if rlp is not None and rlp.sum() > r.sum():
            r = shrink(c, rlp)
        return np.column_stack([c, r])

    tries = 0
    while time.process_time() < deadline:
        tries += 1
        if tries == 1:
            seed = best.copy()
        elif tries % 4 == 1:
            seed = best.copy()
            c = seed[:, :2] + rng.normal(0, 0.006, size=(N, 2))
            c = np.clip(c, 0.0, 1.0)
            r = lp_radii(c)
            if r is None:
                continue
            seed = np.column_stack([c, shrink(c, r)])
        elif tries % 4 == 2:
            seed = best.copy()
            c = seed[:, :2] + rng.normal(0, 0.02, size=(N, 2))
            c = np.clip(c, 0.0, 1.0)
            r = lp_radii(c)
            if r is None:
                continue
            seed = np.column_stack([c, shrink(c, r)])
        elif tries % 4 == 3:
            seed = next_row_seed()
        else:
            seed = random_seed()

        res = run_opt(seed)
        if res is None:
            continue
        sc = res[:, 2].sum()
        if sc > best_score:
            best_score = sc
            best = res.copy()

    # final polish with trust-constr from best
    if time.process_time() < deadline:
        try:
            z0 = to_z(best[:, :2], best[:, 2])
            res = minimize(obj, z0, jac=obj_g, method='trust-constr',
                           constraints=[nlc], bounds=bounds,
                           options={'maxiter': 200, 'gtol': 1e-13,
                                    'xtol': 1e-13, 'barrier_tol': 1e-13})
            c2, r2 = unpack(res.x)
            c2 = np.clip(c2, 0.0, 1.0)
            r2 = shrink(c2, r2)
            rlp = lp_radii(c2)
            if rlp is not None and rlp.sum() > r2.sum():
                r2 = shrink(c2, rlp)
            if r2.sum() > best[:, 2].sum():
                best = np.column_stack([c2, r2])
        except Exception:
            pass

    out = best.copy()
    out[:, 2] *= (1.0 - 1e-9)
    out[:, 2] = np.maximum(out[:, 2], 1e-9)
    return out
